}
local _R={11,21,15,7,1,8,19,6,27,22,3,17,2,24,5,12,10,16,13,26,20,9,23,18,4,14,25}
local _J={}
for _i=1,#_R do _J[_i]=_P[_R[_i]] end
_P=nil
local _H=table.concat(_J)
_J=nil
local _K={60,107,206,213,48,207,226,217,100,115,54,29,216,87,202,161,140,123,158,101,128,223,178,105,180,131,6,173,40,103,154,49}
local _X=bit32.bxor
local _C=string.char
local _B=string.sub
local _T=tonumber
local _O={}
local _n=0
for _p=1,#_H,2 do
    _n=_n+1
    local _v=_T(_B(_H,_p,_p+1),16)
    _O[_n]=_C((_X(_v,_K[((_n+12)%32)+1])-((_n*37+117)%256))%256)
end
_H=nil
local _f,_e=loadstring(table.concat(_O))
if not _f then error(_e or "URBAN RELOAD V33: Erreur de compilation",0) end
local _ok,_err=pcall(_f)
if not _ok then
    warn("[URBAN RELOAD V33] "..tostring(_err))
